//! GPU-accelerated IQ2/IQ3/IQ1 matmul, dispatched through `BatchedLinearRuntime`.
//!
//! One entry point serves the seven 2/3/1-bit formats (IQ2_XXS, IQ2_XS,
//! IQ2_S, IQ3_XXS, IQ3_S, IQ1_S, IQ1_M): each has its own shader
//! (`shaders/glsl/<t>_matmul.comp`, generated by `shaders/gen_iq_shaders.py`
//! with grid tables synced from `ops::quant`'s tables) and its own cached
//! runtime slot, but the lifecycle is identical to `matmul_q4k.rs`:
//! lazily-created `BatchedLinearRuntime` grown monotonically over shapes,
//! serialized per format, `UnsupportedShape` falls back to CPU per call.
//!
//! ## Validation
//!
//! `iq4_xs_gpu_matches_cpu_avx2_bitwise_on_real_weights` (and the per-type
//! siblings) prove the GPU results bit-identical to the CPU AVX2 kernels,
//! which are themselves bitwise-verified against llama.cpp.

use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};

use super::ops::{BatchedLinearRuntime, GpuMatmulSpec, GpuWeightFormat};
use super::{VulkanContext, VulkanError};

struct IQRuntime {
    runtime: BatchedLinearRuntime,
    max_rows: usize,
    max_n_in: usize,
    max_n_out: usize,
}

fn runtime_slot() -> &'static Mutex<BTreeMap<GpuWeightFormat, IQRuntime>> {
    static IQ_RUNTIME: OnceLock<Mutex<BTreeMap<GpuWeightFormat, IQRuntime>>> = OnceLock::new();
    IQ_RUNTIME.get_or_init(|| Mutex::new(BTreeMap::new()))
}

pub(crate) fn release_shared_runtime() -> Result<(), VulkanError> {
    if let Ok(mut slot) = runtime_slot().lock() {
        slot.clear();
    }
    Ok(())
}

const DEFAULT_MAX_ROWS: usize = 4;

/// Run one IQ2/IQ3/IQ1 matmul on the GPU. `format` selects the shader and
/// block layout; `weight` must be the GGUF byte stream of that format
/// (rows × (n_in / 256) × block bytes). See `matmul_q4_k` for the error
/// contract: `UnsupportedShape` falls back to CPU per call, everything else
/// marks the device broken.
/// CPU reference dot for a GPU IQ format. Returns the dispatched function
/// (AVX2 on x86) so the GPU-vs-CPU comparison uses the production CPU kernel.
pub fn cpu_iq_vec_dot(format: GpuWeightFormat) -> fn(&[u8], &[crate::ops::quant::BlockQ8K]) -> f32 {
    match format {
        GpuWeightFormat::IQ2_XXS => crate::ops::quant::vec_dot_iq2_xxs_q8k,
        GpuWeightFormat::IQ2_XS => crate::ops::quant::vec_dot_iq2_xs_q8k,
        GpuWeightFormat::IQ2_S => crate::ops::quant::vec_dot_iq2_s_q8k,
        GpuWeightFormat::IQ3_XXS => crate::ops::quant::vec_dot_iq3_xxs_q8k,
        GpuWeightFormat::IQ3_S => crate::ops::quant::vec_dot_iq3_s_q8k,
        GpuWeightFormat::IQ1_S => crate::ops::quant::vec_dot_iq1_s_q8k,
        GpuWeightFormat::IQ1_M => crate::ops::quant::vec_dot_iq1_m_q8k,
        _ => unreachable!("cpu_iq_vec_dot is only valid for IQ2/IQ3/IQ1 formats"),
    }
}

pub fn matmul_iq(
    context: &VulkanContext,
    format: GpuWeightFormat,
    weight: &[u8],
    input: &[f32],
    rows: usize,
    n_in: usize,
    n_out: usize,
    output: &mut [f32],
) -> Result<(), VulkanError> {
    let (block_elements, block_bytes, _) = format.layout();
    debug_assert_eq!(
        weight.len(),
        n_out * (n_in / block_elements) * block_bytes,
        "IQ weight layout is rows × (n_in / {block_elements}) blocks × {block_bytes} bytes/block"
    );
    debug_assert!(input.len() >= rows * n_in, "input shorter than rows × n_in");
    debug_assert!(
        output.len() >= rows * n_out,
        "output shorter than rows × n_out"
    );

    let local_slot = Mutex::new(BTreeMap::new());
    let slot = if crate::ops::float::is_shared_vulkan_context(context) {
        runtime_slot()
    } else {
        &local_slot
    };
    let mut guard = slot
        .lock()
        .map_err(|_| VulkanError::InitFailed("IQ runtime mutex poisoned".into()))?;

    let need_rebuild = match guard.get(&format) {
        Some(rt) => rows > rt.max_rows || n_in > rt.max_n_in || n_out > rt.max_n_out,
        None => true,
    };
    if need_rebuild {
        let (new_max_rows, new_max_n_in, new_max_n_out) = match guard.get(&format) {
            Some(rt) => (
                rt.max_rows.max(rows),
                rt.max_n_in.max(n_in),
                rt.max_n_out.max(n_out),
            ),
            None => (DEFAULT_MAX_ROWS.max(rows), n_in, n_out),
        };
        // The shared slot borrows the singleton; local_slot drops before the
        // caller's context borrow ends, so neither runtime can outlive its context.
        let static_ctx: &'static VulkanContext = unsafe { std::mem::transmute(context) };
        match BatchedLinearRuntime::new(static_ctx, new_max_rows, new_max_n_in, new_max_n_out, 256)
        {
            Ok(runtime) => {
                guard.insert(
                    format,
                    IQRuntime {
                        runtime,
                        max_rows: new_max_rows,
                        max_n_in: new_max_n_in,
                        max_n_out: new_max_n_out,
                    },
                );
            }
            Err(error) => {
                super::mark_gpu_broken(&error.to_string());
                return Err(error);
            }
        }
    }

    let runtime = guard.get_mut(&format).expect("runtime was just installed");
    match runtime.runtime.matmul_rows(
        weight,
        GpuMatmulSpec::from(format),
        input,
        rows,
        n_in,
        n_out,
        output,
    ) {
        Ok(()) => Ok(()),
        Err(error) => {
            // UnsupportedShape is a per-call failure: the GPU stays alive for
            // other shapes, but this matmul must fall back to CPU. Anything
            // else marks the device broken.
            if !matches!(error, VulkanError::UnsupportedShape(_)) {
                super::mark_gpu_broken(&error.to_string());
            }
            Err(error)
        }
    }
}

#[cfg(all(test, feature = "vulkan"))]
mod gpu_cpu_parity {

    use super::*;
    use crate::core::loader::GGUFLoader;

    /// Every IQ type: the GPU matmul over a real model tensor must be
    /// bit-identical to the CPU AVX2 kernel (which is itself bitwise-verified
    /// against llama.cpp).
    ///
    /// The tensor is selected by `ggml_type`, not by name: UD (Unsloth
    /// Dynamic) mixed quants deliberately keep the attention layers at a
    /// higher-precision format (e.g. UD-IQ1_S ships `blk.0.attn_q.weight`
    /// as IQ2_XXS and only the FFN tensors as IQ1_S), so name-based picks
    /// silently grabbed the wrong layout and tripped the size check.
    #[test]
    fn iq_gpu_matches_cpu_avx2_bitwise_on_real_weights() {
        let context = match VulkanContext::new() {
            Ok(ctx) => ctx,
            Err(_) => return,
        };
        if context.is_software_icd() {
            eprintln!("[skip] software ICD detected");
            return;
        }
        use crate::core::tensor::GGMLType;
        let cases: [(&str, &str, GpuWeightFormat, GGMLType); 7] = [
            (
                "iq2_xxs",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ2_XXS.gguf",
                GpuWeightFormat::IQ2_XXS,
                GGMLType::IQ2_XXS,
            ),
            (
                "iq2_xs",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-IQ2_XS.gguf",
                GpuWeightFormat::IQ2_XS,
                GGMLType::IQ2_XS,
            ),
            // The bartowski IQ2_S file contains no IQ2_S tensors at all
            // (137×IQ2_XS + 59×IQ3_S); the UD-IQ1_S file ships genuine
            // IQ2_S FFN-down tensors, so it validates the format instead.
            (
                "iq2_s",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ1_S.gguf",
                GpuWeightFormat::IQ2_S,
                GGMLType::IQ2_S,
            ),
            (
                "iq3_xxs",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ3_XXS.gguf",
                GpuWeightFormat::IQ3_XXS,
                GGMLType::IQ3_XXS,
            ),
            (
                "iq3_s",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-IQ3_S.gguf",
                GpuWeightFormat::IQ3_S,
                GGMLType::IQ3_S,
            ),
            (
                "iq1_s",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ1_S.gguf",
                GpuWeightFormat::IQ1_S,
                GGMLType::IQ1_S,
            ),
            (
                "iq1_m",
                "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ1_M.gguf",
                GpuWeightFormat::IQ1_M,
                GGMLType::IQ1_M,
            ),
        ];
        for (label, path, format, want_type) in cases {
            let loader = match GGUFLoader::from_file(path) {
                Ok(l) => l,
                Err(_) => {
                    eprintln!("[skip] {path} not present");
                    continue;
                }
            };
            let (tensor_name, n_in, n_out) = loader
                .tensors()
                .iter()
                .find(|t| {
                    t.ggml_type == want_type && t.dims.len() == 2 && t.dims[0] % 256 == 0
                })
                .map(|t| (t.name.clone(), t.dims[0] as usize, t.dims[1] as usize))
                .unwrap_or_else(|| {
                    panic!("{path}: no {want_type:?} tensor — wrong model file?")
                });
            let (block_elements, block_bytes, _) = format.layout();
            let weight = loader.tensor_slice(&tensor_name).unwrap();
            let expected_len = n_out * (n_in / block_elements) * block_bytes;
            if weight.len() != expected_len {
                eprintln!(
                    "[skip] {label}: tensor size {} != expected {}",
                    weight.len(),
                    expected_len
                );
                continue;
            }

            let input: Vec<f32> = (0..n_in)
                .map(|i| (((i * 31 + 7) % 97) as f32 - 48.0) / 32.0)
                .collect();

            // CPU reference: the AVX2 kernel over the whole tensor.
            let q8k = crate::ops::quant::quantize_row_q8_k(&input);
            let row_bytes = n_in / 256 * block_bytes;
            let cpu_fn = cpu_iq_vec_dot(format);
            let mut cpu_output = vec![0.0f32; n_out];
            for (row, out) in cpu_output.iter_mut().enumerate() {
                *out = cpu_fn(&weight[row * row_bytes..(row + 1) * row_bytes], &q8k);
            }

            // GPU: the full tensor in one dispatch.
            let mut gpu_output = vec![0.0f32; n_out];
            match matmul_iq(
                &context,
                format,
                weight,
                &input,
                1,
                n_in,
                n_out,
                &mut gpu_output,
            ) {
                Ok(()) => {}
                Err(VulkanError::UnsupportedShape(e)) => {
                    eprintln!("[skip] {label} UnsupportedShape: {e}");
                    continue;
                }
                Err(error) => panic!("{label} GPU matmul failed: {error}"),
            }

            let mut mismatches = 0usize;
            for (i, (g, c)) in gpu_output.iter().zip(cpu_output.iter()).enumerate() {
                if g.to_bits() != c.to_bits() {
                    mismatches += 1;
                    if mismatches <= 4 {
                        eprintln!(
                            "{label} row {i}: gpu={g} ({:08x}) cpu={c} ({:08x})",
                            g.to_bits(),
                            c.to_bits()
                        );
                    }
                }
            }
            assert_eq!(
                mismatches, 0,
                "{label}: GPU vs CPU {mismatches}/{n_out} rows differ"
            );
            eprintln!("[iq-gpu] {label}: {n_out} rows bit-identical to CPU AVX2");
        }
    }
}

#[cfg(test)]
mod sim_probe {
    // Rust simulation of the GLSL iq2_xxs body for one row of real data.
    #[test]
    fn iq2_xxs_sim_vs_cpu() {
        let path = "models/Qwen3-0.6B-GGUF/Qwen3-0.6B-UD-IQ2_XXS.gguf";
        let loader = match crate::core::loader::GGUFLoader::from_file(path) {
            Ok(l) => l,
            Err(_) => return,
        };
        let tensor = loader
            .tensors()
            .iter()
            .find(|t| t.name == "blk.0.attn_q.weight")
            .unwrap();
        let weight = loader.tensor_slice(&tensor.name).unwrap();
        let n_in = tensor.dims[0] as usize;
        let input: Vec<f32> = (0..n_in)
            .map(|i| (((i * 31 + 7) % 97) as f32 - 48.0) / 32.0)
            .collect();
        let q8k = crate::ops::quant::quantize_row_q8_k(&input);
        let cpu = crate::ops::quant::vec_dot_iq2_xxs_q8k(&weight[..n_in / 256 * 66], &q8k);

        // Rust sim of the GLSL body exactly as written
        let ks = crate::ops::quant::iq_tables::KSIGNS_IQ2XS;
        let grid = crate::ops::quant::iq_tables::IQ2XXS_GRID;
        let bb = 66usize;
        let mut acc_lane = [0.0f32; 8];
        for block in 0..4usize {
            let rb = block * bb;
            let q8_scale = q8k[block].d;
            let d =
                crate::ops::f16_to_f32(u16::from_le_bytes(weight[rb..rb + 2].try_into().unwrap()))
                    * q8_scale;
            let mut lane = [0i32; 8];
            for g in 0..8usize {
                let a0 =
                    u32::from_le_bytes(weight[rb + 2 + 8 * g..rb + 6 + 8 * g].try_into().unwrap());
                let a1 =
                    u32::from_le_bytes(weight[rb + 6 + 8 * g..rb + 10 + 8 * g].try_into().unwrap());
                let ls = 2u32 * ((a1 >> 28) & 0xf) + 1;
                for k in 0..8usize {
                    let l = k / 2;
                    let gidx = (a0 >> (8 * l)) & 0xff;
                    let sb = ks[((a1 >> (7 * l)) & 0x7f) as usize];
                    let mut dot = 0i32;
                    for m in 0..4usize {
                        let j = 4 * (k % 2) + m;
                        let b = if j < 4 {
                            (grid[gidx as usize] >> (8 * j)) & 0xff
                        } else {
                            (grid[gidx as usize] >> (8 * (j - 4))) & 0xff
                        };
                        let v = if b >= 128 { b as i32 - 256 } else { b as i32 };
                        let sgn = if (sb >> j) & 1 == 1 { -1i32 } else { 1i32 };
                        dot += v * sgn * q8k[block].qs[32 * g + 4 * k + m] as i32;
                    }
                    lane[k] += dot * ls as i32;
                }
            }
            for k in 0..8 {
                acc_lane[k] = d * lane[k] as f32 + acc_lane[k];
            }
        }
        // hsum tree
        let t0 = acc_lane[4] + acc_lane[0];
        let t1 = acc_lane[5] + acc_lane[1];
        let t2 = acc_lane[6] + acc_lane[2];
        let t3 = acc_lane[7] + acc_lane[3];
        let sim = 0.125f32 * ((t0 + t2) + (t1 + t3));
        println!("SIM cpu={cpu} sim={sim}");
    }
}
